async function aiStatus(request,env){const a=await requirePerm(request,env,'ai:read');if(a.error)return a.error;return j({configured:!!env.AI,provider:env.AI?'cloudflare-workers-ai':null,model:text(env.ADMIN_AI_MODEL,120)||'@cf/meta/llama-3.1-8b-instruct',rules:['Read-only recommendations','No bans, refunds, deletions or verification decisions','No private-message content in context','Prompts and generated text are not stored in usage telemetry']})}
async function aiContext(env,workspace){if(workspace==='moderation'){const r=await list(env,'reports','category,status,created_at','created_at.desc',30);return{reports:r.ok?r.data:[]}}if(workspace==='verification'){const r=await list(env,'verification_requests','verification_type,status,submitted_at','submitted_at.desc',30);return{verification:r.ok?r.data:[]}}if(workspace==='cms'){const r=await list(env,'hc_cms_posts','title,status,scheduled_for,published_at,updated_at','updated_at.desc',30);return{posts:r.ok?r.data:[]}}if(workspace==='payments'){for(const t of PAYMENT_TABLES){const r=await list(env,t,'id,status,currency,amount_minor,created_at','created_at.desc',30);if(r.ok)return{source:t,transactions:r.data}}return{transactions:[],note:'No native payment table is currently available.'}}const [profiles,reports,verify,posts]=await Promise.all([list(env,'dating_profiles','user_id,verification_level,is_discoverable,created_at','created_at.desc',50),list(env,'reports','category,status,created_at','created_at.desc',50),list(env,'verification_requests','verification_type,status,submitted_at','submitted_at.desc',50),list(env,'hc_cms_posts','status,created_at,published_at','created_at.desc',50)]);return{profiles:profiles.ok?profiles.data:[],reports:reports.ok?reports.data:[],verification:verify.ok?verify.data:[],posts:posts.ok?posts.data:[]}}
async function aiAsk(request,env){const a=await requirePerm(request,env,'ai:write');if(a.error)return a.error;let b;try{b=await jsonBody(request,20000)}catch(e){return j({error:e.message},e.status||400)}const prompt=text(b.prompt,1500),workspace=text(b.workspace||'overview',30);if(prompt.length<3)return j({error:'Enter an Admin AI question.'},400);if(!['overview','moderation','verification','payments','cms'].includes(workspace))return j({error:'Choose a supported AI workspace.'},400);if(!env.AI){await svc(env,'/rest/v1/hc_admin_ai_usage',{method:'POST',body:{actor_user_id:a.actor.userId,actor_email:a.actor.email,actor_role:a.actor.role,workspace,prompt_chars:prompt.length,provider:'cloudflare-workers-ai',outcome:'unavailable'},headers:{Prefer:'return=minimal'}});return j({error:'Admin AI is not configured on this Cloudflare Worker yet.',configured:false},503)}const context=await aiContext(env,workspace),model=text(env.ADMIN_AI_MODEL,120)||'@cf/meta/llama-3.1-8b-instruct',system='You are Heart Connect Admin AI. Give concise operational analysis and drafting help only. Never execute actions, claim an action happened, expose credentials, infer protected traits, or request private message content. Distinguish observed data from recommendations. For bans, suspensions, refunds, deletion, moderation and verification decisions, explain that a human authorized admin must review and confirm.';try{const r=await env.AI.run(model,{messages:[{role:'system',content:system},{role:'user',content:'Workspace: '+workspace+'\nBounded operational context: '+JSON.stringify(cleanObject(context)).slice(0,24000)+'\nAdmin request: '+prompt}]});const answer=text(r?.response||r?.result?.response||r?.text||'',5000)||'The configured AI provider returned no text.';await svc(env,'/rest/v1/hc_admin_ai_usage',{method:'POST',body:{actor_user_id:a.actor.userId,actor_email:a.actor.email,actor_role:a.actor.role,workspace,prompt_chars:prompt.length,provider:'cloudflare-workers-ai',outcome:'success'},headers:{Prefer:'return=minimal'}});await audit(env,a.actor,'admin.ai.ask',workspace,'',{promptChars:prompt.length});return j({answer,workspace,model,requiresHumanAction:true})}catch{await svc(env,'/rest/v1/hc_admin_ai_usage',{method:'POST',body:{actor_user_id:a.actor.userId,actor_email:a.actor.email,actor_role:a.actor.role,workspace,prompt_chars:prompt.length,provider:'cloudflare-workers-ai',outcome:'failed'},headers:{Prefer:'return=minimal'}});return j({error:'Admin AI is temporarily unavailable.'},503)}}

function adminHtml(){return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Heart Connect Admin · Phase 2</title><style>
:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#eef1f8;background:#070910}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 12% 0,#281225 0,#0b0e16 36%,#06080e 76%);min-height:100vh}button,input,textarea,select{font:inherit}.shell{display:grid;grid-template-columns:270px 1fr;min-height:100vh}.side{padding:24px 17px;border-right:1px solid #ffffff12;background:#080b12ed;position:sticky;top:0;height:100vh;overflow:auto}.brand{display:flex;gap:12px;align-items:center;margin:0 8px 24px}.mark{width:44px;height:44px;border-radius:14px;display:grid;place-items:center;background:linear-gradient(135deg,#ff4d7d,#8b4cff);font-weight:900}.brand b{display:block}.brand small,.muted{color:#8f98aa}.phase{font-size:11px;color:#ff86a7;letter-spacing:.12em}.nav{display:grid;gap:6px}.nav button{border:0;color:#aeb7ca;background:transparent;padding:11px 12px;border-radius:11px;text-align:left;cursor:pointer}.nav button:hover,.nav button.active{background:#ffffff0d;color:#fff}.main{padding:28px;min-width:0}.top{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:20px}.top h1{font-size:28px;margin:4px 0}.pill{border:1px solid #ffffff1c;background:#ffffff08;border-radius:999px;padding:8px 12px;color:#aeb7ca}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px}.card,.panel{border:1px solid #ffffff13;background:#10141fdd;border-radius:18px;box-shadow:0 14px 45px #0006}.card{padding:18px;text-align:left;color:inherit;cursor:pointer}.card span{display:block;color:#929caf;font-size:11px;text-transform:uppercase;letter-spacing:.08em}.card strong{display:block;font-size:27px;margin:8px 0}.panel{padding:18px;margin-top:14px}.panel-head{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:13px}.panel h2,.panel h3{margin:0}.toolbar,.actions{display:flex;gap:8px;flex-wrap:wrap}.field{display:grid;gap:6px;margin:10px 0}.field span{font-size:12px;color:#9aa3b5}.field input,.field textarea,.field select,.toolbar input{width:100%;background:#090c13;border:1px solid #ffffff18;color:#fff;border-radius:10px;padding:10px 12px}.field textarea{min-height:120px;resize:vertical}.toolbar input{min-width:250px}.btn{border:1px solid #ffffff1a;background:#ffffff0c;color:#fff;border-radius:10px;padding:9px 12px;cursor:pointer}.btn:hover{background:#ffffff17}.btn.primary{background:#d72b63;border-color:#ed4d7d}.btn.warn{background:#4a3512;border-color:#6c4b12}.btn.danger{background:#4e1721;border-color:#7e2839}.table{display:grid;gap:7px}.row{display:grid;grid-template-columns:minmax(190px,2fr) repeat(3,minmax(100px,1fr)) 100px;gap:10px;align-items:center;padding:12px;border-radius:11px;background:#090d15;border:1px solid #ffffff0b}.row small{display:block;color:#8f98aa}.status{display:inline-flex;width:max-content;padding:4px 8px;border-radius:999px;background:#ffffff0d;color:#c0c7d5}.status.pending,.status.new,.status.reviewing,.status.suspended{background:#ffb02017;color:#ffc85a}.status.active,.status.approved,.status.published{background:#29c77c18;color:#55e39a}.status.banned,.status.rejected,.status.failed,.status.dismissed{background:#ff4f6d18;color:#ff8597}.empty,.notice{padding:16px;border-radius:12px}.empty{text-align:center;color:#8f98aa;border:1px dashed #ffffff18}.notice{background:#281929;border:1px solid #ff5b8830;margin-bottom:14px}.note{font-size:12px;color:#929caf;margin-top:10px}.split{display:grid;grid-template-columns:1fr 1fr;gap:14px}.editor{display:grid;grid-template-columns:1fr 1fr;gap:10px}.editor .wide{grid-column:1/-1}.json{white-space:pre-wrap;word-break:break-word;background:#070a10;border:1px solid #ffffff12;border-radius:12px;padding:12px;color:#bcc5d5;max-height:46vh;overflow:auto}dialog{border:1px solid #ffffff20;border-radius:18px;background:#0d111a;color:#fff;max-width:820px;width:calc(100% - 28px);padding:0;box-shadow:0 30px 100px #000b}dialog::backdrop{background:#000a}.modal-head{padding:15px 18px;border-bottom:1px solid #ffffff12;display:flex;justify-content:space-between;align-items:center}.modal-body{padding:18px;max-height:75vh;overflow:auto}.modal-head button{background:none;border:0;color:#fff;font-size:22px;cursor:pointer}.ai-answer{white-space:pre-wrap;line-height:1.55;background:#0a0e16;border-radius:13px;padding:15px;border:1px solid #ffffff12}.check{display:flex;gap:8px;align-items:center}.check input{width:auto}@media(max-width:1050px){.shell{grid-template-columns:1fr}.side{height:auto;position:static;border-right:0;border-bottom:1px solid #ffffff12}.nav{display:flex;overflow:auto}.nav button{white-space:nowrap}.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:720px){.main{padding:17px}.grid,.split,.editor{grid-template-columns:1fr}.editor .wide{grid-column:auto}.row{grid-template-columns:1fr 1fr}.row>*:nth-child(3),.row>*:nth-child(4){display:none}.top{display:block}.pill{display:inline-block;margin-top:8px}.toolbar input{min-width:0}}
</style></head><body><div class="shell"><aside class="side"><div class="brand"><div class="mark">HC</div><div><b>Heart Connect</b><small>Admin Control Plane</small><div class="phase">PHASE 2</div></div></div><div class="nav" id="nav"></div></aside><main class="main"><div class="top"><div><div class="phase">RESTRICTED OPERATIONS</div><h1 id="title">Admin Overview</h1><div class="muted" id="actor">Checking access…</div></div><div class="pill">${VERSION}</div></div><div id="notice"></div><div id="view"></div></main></div><dialog id="modal"><div class="modal-head"><b id="modalTitle">Details</b><button id="modalClose">×</button></div><div class="modal-body" id="modalBody"></div></dialog><script>
const tabs=[['overview','Overview'],['users','Users'],['payments','Payments'],['markets','Markets'],['moderation','Moderation'],['verification','Verification'],['cms','Blog & CMS'],['notifications','Notifications'],['analytics','Analytics'],['ai','AI Assistant'],['settings','Settings'],['audit','Audit Log']];let caps,current='overview',cmsEditing=null;const nav=document.getElementById('nav'),view=document.getElementById('view'),title=document.getElementById('title'),notice=document.getElementById('notice'),modal=document.getElementById('modal'),modalTitle=document.getElementById('modalTitle'),modalBody=document.getElementById('modalBody');document.getElementById('modalClose').onclick=()=>modal.close();
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function st(v){return '<span class="status '+esc(v)+'">'+esc(v||'—')+'</span>'}function say(m){notice.innerHTML=m?'<div class="notice">'+esc(m)+'</div>':''}function open(title,html){modalTitle.textContent=title;modalBody.innerHTML=html;modal.showModal()}async function req(url,opt={}){const r=await fetch(url,{credentials:'same-origin',...opt});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Object.assign(new Error(d.error||'Request failed.'),{data:d,status:r.status});return d}function post(url,b){return req(url,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(b)})}function buildNav(){nav.innerHTML=tabs.filter(([id])=>id==='overview'||caps?.sections?.[id]).map(([id,label])=>'<button data-tab="'+id+'" class="'+(id===current?'active':'')+'">'+label+'</button>').join('');nav.querySelectorAll('button').forEach(b=>b.onclick=()=>load(b.dataset.tab))}function card(l,v,t){return '<button class="card" data-open="'+t+'"><span>'+esc(l)+'</span><strong>'+(v==null?'—':esc(v))+'</strong><small class="muted">Open '+esc(t)+'</small></button>'}function wireOpen(){view.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>load(b.dataset.open))}
async function load(tab){current=tab;buildNav();title.textContent=tabs.find(x=>x[0]===tab)?.[1]||'Admin';view.innerHTML='<div class="empty">Loading…</div>';say('');try{if(tab==='overview')return overview(await req('/api/admin/overview'));if(tab==='users')return users(await req('/api/admin/users'));if(tab==='payments')return payments(await req('/api/admin/payments'));if(tab==='moderation')return moderation(await req('/api/admin/moderation'));if(tab==='verification')return verification(await req('/api/admin/verifications'));if(tab==='cms')return cms(await req('/api/admin/cms/posts'));if(tab==='ai')return ai(await req('/api/admin/ai/status'));if(tab==='audit')return simple('Audit Log',await req('/api/admin/audit'));if(tab==='markets')return simple('Market Control',await req('/api/admin/markets'));return coming(tab)}catch(e){view.innerHTML='<div class="empty">'+esc(e.message)+'</div>';if(e.data?.hint)say(e.data.hint)}}
function overview(d){const m=d.metrics||{};view.innerHTML='<div class="grid">'+card('Profiles',m.profiles,'users')+card('Open reports',m.openReports,'moderation')+card('Pending verification',m.pendingVerifications,'verification')+card('Published posts',m.publishedPosts,'cms')+'</div><section class="panel"><h2>Phase 2 controls</h2><p class="note">Advanced user actions, moderation decisions, verification decisions, transaction detail, CMS editing/media and the read-only Admin AI workspace are now wired on this isolated branch. The Supabase Phase 2 migration must be applied only after branch reconciliation.</p></section>';wireOpen()}
function users(d){view.innerHTML='<section class="panel"><div class="panel-head"><h2>User Management</h2><div class="toolbar"><input id="uq" placeholder="Search name, city, country or ID"><button class="btn" id="us">Search</button></div></div><div class="table">'+(d.items?.length?d.items.map(x=>'<div class="row"><div><b>'+esc(x.display_name||'Unnamed')+'</b><small>'+esc(x.city||'')+(x.country?' · '+esc(x.country):'')+'</small></div><div>'+esc(x.relationship_intention||'—')+'</div><div>'+st(x.admin_state?.status||'active')+'</div><div>'+esc(x.verification_level||'unverified')+'</div><button class="btn" data-user="'+esc(x.user_id)+'">Manage</button></div>').join(''):'<div class="empty">No profiles returned.</div>')+'</div></section>';document.getElementById('us').onclick=async()=>users(await req('/api/admin/users?q='+encodeURIComponent(document.getElementById('uq').value)));view.querySelectorAll('[data-user]').forEach(b=>b.onclick=()=>manageUser(b.dataset.user))}
async function manageUser(id){try{const d=await req('/api/admin/users/'+encodeURIComponent(id)),p=d.profile,s=d.adminState||{};open((p.display_name||'User')+' · Management','<div class="split"><div><h3>Profile</h3><div class="json">'+esc(JSON.stringify(p,null,2))+'</div></div><div><h3>Control state</h3><p>'+st(s.status||'active')+'</p><p class="note">'+esc(d.enforcementNote||'')+'</p><div class="actions"><button class="btn" id="uActivate">Set active</button><button class="btn warn" id="uRestrict">Restrict</button><button class="btn warn" id="uSuspend">Suspend</button><button class="btn danger" id="uBan">Ban</button><button class="btn danger" id="uDelete">Prepare deletion</button></div><hr><label class="check"><input id="fHome" type="checkbox" '+(s.featured_on_home?'checked':'')+'> Featured on home</label><label class="check"><input id="fDiscover" type="checkbox" '+(s.featured_in_discover?'checked':'')+'> Featured in discover</label><button class="btn" id="saveFeatures">Save feature flags</button></div></div><h3>Recent admin history</h3><div class="json">'+esc(JSON.stringify(d.history||[],null,2))+'</div>');document.getElementById('uActivate').onclick=()=>state(id,'active');document.getElementById('uRestrict').onclick=()=>state(id,'restricted');document.getElementById('uSuspend').onclick=()=>state(id,'suspended');document.getElementById('uBan').onclick=()=>state(id,'banned');document.getElementById('uDelete').onclick=()=>state(id,'deletion_pending');document.getElementById('saveFeatures').onclick=async()=>{await post('/api/admin/users/'+id+'/features',{featuredOnHome:document.getElementById('fHome').checked,featuredInDiscover:document.getElementById('fDiscover').checked,reason:'Updated from Phase 2 admin console'});say('Feature flags saved.');modal.close();load('users')}}catch(e){say(e.message)}}
async function state(id,status){const reason=status==='active'?'Restored by authorized admin':prompt('Reason for '+status+':','');if(status!=='active'&&!reason)return;let confirmation='';if(status==='suspended')confirmation=prompt('Type SUSPEND to confirm:','')||'';if(status==='banned')confirmation=prompt('Type BAN to confirm:','')||'';if(status==='deletion_pending')confirmation=prompt('Type DELETE to confirm soft deletion preparation:','')||'';let suspendedUntil=null;if(status==='suspended')suspendedUntil=prompt('Optional suspension end (ISO date/time). Leave blank for indefinite:','')||null;try{const d=await post('/api/admin/users/'+id+'/state',{status,reason,confirmation,suspendedUntil});say(d.note||'Account state saved.');modal.close();load('users')}catch(e){say(e.message+(e.data?.confirmation?' Type '+e.data.confirmation+'.':''))}}
function payments(d){if(!d.available){view.innerHTML='<section class="panel"><h2>Payment Operations</h2><div class="empty">'+esc(d.note||'Native payment table is not ready.')+'</div></section>';return}view.innerHTML='<section class="panel"><div class="panel-head"><h2>Payment Operations</h2><span class="muted">'+esc(d.source)+'</span></div><div class="table">'+(d.items?.length?d.items.map(x=>'<div class="row"><div><b>'+esc(x.kind||x.provider||'Transaction')+'</b><small>'+esc(x.id||'')+'</small></div><div>'+esc(x.currency||'')+' '+esc(x.amount_minor??x.amountMinor??'—')+'</div><div>'+st(x.status||'unknown')+'</div><div>'+esc(x.created_at||x.createdAt||'')+'</div><button class="btn" data-pay="'+esc(x.id)+'" data-source="'+esc(d.source)+'">Open</button></div>').join(''):'<div class="empty">No transactions returned.</div>')+'</div><p class="note">Phase 2 transaction views are read-only. No fake refund or success controls are exposed.</p></section>';view.querySelectorAll('[data-pay]').forEach(b=>b.onclick=async()=>{try{const x=await req('/api/admin/payments/'+encodeURIComponent(b.dataset.pay)+'?source='+encodeURIComponent(b.dataset.source));open('Transaction details','<div class="json">'+esc(JSON.stringify(x,null,2))+'</div>')}catch(e){say(e.message)}})}
function moderation(d){view.innerHTML='<section class="panel"><div class="panel-head"><h2>Moderation Queue</h2><span class="muted">Human decision required</span></div><div class="table">'+(d.items?.length?d.items.map(x=>'<div class="row"><div><b>'+esc(x.category)+'</b><small>'+esc(x.reported_user_id)+'</small></div><div>'+st(x.status)+'</div><div>'+esc(x.created_at||'')+'</div><div>'+esc((x.details||'').slice(0,80))+'</div><button class="btn" data-report="'+esc(x.id)+'">Review</button></div>').join(''):'<div class="empty">No reports returned.</div>')+'</div></section>';view.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>reviewReport(b.dataset.report))}
function reviewReport(id){open('Moderation decision','<label class="field"><span>Review note</span><textarea id="modNote" placeholder="Document the reason for the decision"></textarea></label><div class="actions"><button class="btn" id="mReview">Mark reviewing</button><button class="btn" id="mDismiss">Dismiss</button><button class="btn danger" id="mAction">Actioned</button></div><p class="note">Actioned does not automatically ban a member. Use User Management for a separate explicit restriction.</p>');for(const [el,status] of [['mReview','reviewing'],['mDismiss','dismissed'],['mAction','actioned']])document.getElementById(el).onclick=async()=>{try{await post('/api/admin/moderation/'+id+'/review',{status,note:document.getElementById('modNote').value});modal.close();say('Moderation decision saved and audited.');load('moderation')}catch(e){say(e.message)}}}
function verification(d){view.innerHTML='<section class="panel"><div class="panel-head"><h2>Verification Queue</h2><span class="muted">Audited evidence access</span></div><div class="table">'+(d.items?.length?d.items.map(x=>'<div class="row"><div><b>'+esc(x.verification_type)+'</b><small>'+esc(x.user_id)+'</small></div><div>'+st(x.status)+'</div><div>'+esc(x.submitted_at||'')+'</div><div>'+esc(x.rejection_reason||'—')+'</div><button class="btn" data-ver="'+esc(x.id)+'" data-status="'+esc(x.status)+'">Review</button></div>').join(''):'<div class="empty">No requests returned.</div>')+'</div></section>';view.querySelectorAll('[data-ver]').forEach(b=>b.onclick=()=>reviewVerification(b.dataset.ver,b.dataset.status))}
function reviewVerification(id,status){open('Verification review','<div class="actions"><button class="btn" id="vEvidence">Open evidence link</button><button class="btn primary" id="vApprove" '+(status!=='pending'?'disabled':'')+'>Approve</button><button class="btn danger" id="vReject" '+(status!=='pending'?'disabled':'')+'>Reject</button></div><label class="field"><span>Review / rejection note</span><textarea id="vNote"></textarea></label><p class="note">Evidence links expire after five minutes. Approval never downgrades an existing stronger verification level.</p>');document.getElementById('vEvidence').onclick=async()=>{try{const d=await req('/api/admin/verifications/'+id+'/evidence');window.open(d.url,'_blank','noopener,noreferrer')}catch(e){say(e.message)}};document.getElementById('vApprove').onclick=()=>verDecision(id,'approve');document.getElementById('vReject').onclick=()=>verDecision(id,'reject')}
async function verDecision(id,decision){try{await post('/api/admin/verifications/'+id+'/review',{decision,note:document.getElementById('vNote').value});modal.close();say('Verification decision saved and audited.');load('verification')}catch(e){say(e.message)}}
function cms(d){view.innerHTML='<div class="split"><section class="panel"><div class="panel-head"><h2>Posts</h2><button class="btn primary" id="newPost">New post</button></div><div class="table">'+(d.items?.length?d.items.map(x=>'<div class="row"><div><b>'+esc(x.title)+'</b><small>/'+esc(x.slug)+'</small></div><div>'+st(x.status)+'</div><div>'+esc(x.scheduled_for||x.published_at||'')+'</div><div>'+esc(x.updated_at||'')+'</div><button class="btn" data-post="'+encodeURIComponent(JSON.stringify(x))+'">Edit</button></div>').join(''):'<div class="empty">No CMS posts yet.</div>')+'</div></section><section class="panel"><h2>Media library</h2><label class="field"><span>Upload image or video</span><input id="cmsFile" type="file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm"></label><label class="field"><span>Alt text</span><input id="cmsAlt"></label><button class="btn" id="cmsUpload">Upload media</button><div id="mediaResult" class="note"></div></section></div><section class="panel" id="editor"></section>';document.getElementById('newPost').onclick=()=>editPost(null);view.querySelectorAll('[data-post]').forEach(b=>b.onclick=()=>editPost(JSON.parse(decodeURIComponent(b.dataset.post))));document.getElementById('cmsUpload').onclick=uploadMedia;editPost(null)}
function editPost(p){cmsEditing=p;const e=document.getElementById('editor');e.innerHTML='<h2>'+(p?'Edit post':'Create post')+'</h2><div class="editor"><label class="field"><span>Title</span><input id="cTitle" value="'+esc(p?.title||'')+'"></label><label class="field"><span>Slug</span><input id="cSlug" value="'+esc(p?.slug||'')+'" placeholder="auto-from-title"></label><label class="field wide"><span>Excerpt</span><textarea id="cExcerpt">'+esc(p?.excerpt||'')+'</textarea></label><label class="field wide"><span>Body</span><textarea id="cBody" style="min-height:260px">'+esc(p?.body||'')+'</textarea></label><label class="field"><span>Status</span><select id="cStatus">'+['draft','scheduled','published','archived'].map(x=>'<option '+(p?.status===x?'selected':'')+'>'+x+'</option>').join('')+'</select></label><label class="field"><span>Schedule time</span><input id="cSchedule" type="datetime-local"></label><label class="field"><span>SEO title</span><input id="cSeoTitle" value="'+esc(p?.seo_title||'')+'"></label><label class="field"><span>SEO description</span><input id="cSeoDescription" value="'+esc(p?.seo_description||'')+'"></label><div class="wide actions"><button class="btn primary" id="savePost">Save post</button></div></div><p class="note">Saving an edit creates a revision snapshot first. Social-channel flags can be stored later, but external publishing is never reported as successful without real APIs.</p>';document.getElementById('savePost').onclick=savePost}
async function savePost(){try{const d=await post('/api/admin/cms/posts',{id:cmsEditing?.id||undefined,title:document.getElementById('cTitle').value,slug:document.getElementById('cSlug').value,excerpt:document.getElementById('cExcerpt').value,body:document.getElementById('cBody').value,status:document.getElementById('cStatus').value,scheduledFor:document.getElementById('cSchedule').value,seoTitle:document.getElementById('cSeoTitle').value,seoDescription:document.getElementById('cSeoDescription').value});say('CMS post saved: /'+d.post.slug);load('cms')}catch(e){say(e.message)}}
async function uploadMedia(){const f=document.getElementById('cmsFile').files[0];if(!f)return say('Choose a media file first.');const fd=new FormData();fd.append('file',f);fd.append('altText',document.getElementById('cmsAlt').value);if(cmsEditing?.id)fd.append('postId',cmsEditing.id);try{const d=await req('/api/admin/cms/media',{method:'POST',body:fd});document.getElementById('mediaResult').textContent=d.item.public_url||'Uploaded';say('CMS media uploaded and audited.')}catch(e){say(e.message)}}
function ai(s){view.innerHTML='<section class="panel"><div class="panel-head"><h2>Admin AI Workspace</h2>'+st(s.configured?'active':'not configured')+'</div><div class="split"><div><label class="field"><span>Workspace</span><select id="aiSpace"><option>overview</option><option>moderation</option><option>verification</option><option>payments</option><option>cms</option></select></label><label class="field"><span>Ask for analysis, a summary, or a draft</span><textarea id="aiPrompt" placeholder="Summarize the operational risks I should review today."></textarea></label><button class="btn primary" id="aiRun" '+(!s.configured?'disabled':'')+'>Run Admin AI</button><p class="note">'+esc((s.rules||[]).join(' · '))+'</p></div><div id="aiAnswer" class="ai-answer">'+(s.configured?'Ready. AI is advisory only.':'Cloudflare Workers AI binding is not configured yet; no fake AI response will be generated.')+'</div></div></section>';document.getElementById('aiRun').onclick=async()=>{const box=document.getElementById('aiAnswer');box.textContent='Working…';try{const d=await post('/api/admin/ai/ask',{workspace:document.getElementById('aiSpace').value,prompt:document.getElementById('aiPrompt').value});box.textContent=d.answer}catch(e){box.textContent=e.message}}}
function simple(name,d){view.innerHTML='<section class="panel"><h2>'+esc(name)+'</h2><div class="json">'+esc(JSON.stringify(d,null,2))+'</div></section>'}function coming(tab){const copy={notifications:'Notification sending controls remain staged for a later phase so delivery providers and audience safeguards can be reviewed first.',analytics:'Advanced analytics remains staged until native aggregate counters are reconciled with the security/backend work.',settings:'Site-wide settings and staff permission mutation remain staged for the next phase.'};view.innerHTML='<section class="panel"><h2>'+esc(tabs.find(x=>x[0]===tab)?.[1]||tab)+'</h2><div class="empty">'+esc(copy[tab]||'This section remains staged.')+'</div></section>'}
(async()=>{try{caps=await req('/api/admin/capabilities');document.getElementById('actor').textContent=(caps.actor.displayName||caps.actor.email)+' · '+caps.actor.role+(caps.serviceRoleConfigured?' · native admin data connected':' · admin data secret not configured');buildNav();load('overview')}catch(e){view.innerHTML='<div class="empty"><b>Restricted admin area</b><p>'+esc(e.message)+'</p>'+(e.data?.hint?'<p>'+esc(e.data.hint)+'</p>':'')+'</div>';document.getElementById('actor').textContent='No admin session'}})();
</script></body></html>`}

export async function handleAdmin(request,env){const u=new URL(request.url);if(u.pathname==='/admin'||u.pathname==='/admin/')return page(adminHtml());if(!u.pathname.startsWith('/api/admin/'))return null;if(!sameOrigin(request))return j({error:'Cross-site admin request blocked.'},403);if(request.method==='OPTIONS')return new Response(null,{status:204,headers:{allow:'GET, POST, HEAD, OPTIONS'}});if(u.pathname==='/api/admin/capabilities'&&request.method==='GET')return capabilitiesV2(request,env);
let m=u.pathname.match(/^\/api\/admin\/users\/([^/]+)$/);if(m&&request.method==='GET')return userDetail(request,env,m[1]);m=u.pathname.match(/^\/api\/admin\/users\/([^/]+)\/state$/);if(m&&request.method==='POST')return userState(request,env,m[1]);m=u.pathname.match(/^\/api\/admin\/users\/([^/]+)\/features$/);if(m&&request.method==='POST')return userFeatures(request,env,m[1]);m=u.pathname.match(/^\/api\/admin\/payments\/([^/]+)$/);if(m&&request.method==='GET')return paymentDetail(request,env,m[1]);m=u.pathname.match(/^\/api\/admin\/moderation\/([^/]+)\/review$/);if(m&&request.method==='POST')return moderationReview(request,env,m[1]);m=u.pathname.match(/^\/api\/admin\/verifications\/([^/]+)\/evidence$/);if(m&&request.method==='GET')return verificationEvidence(request,env,m[1]);m=u.pathname.match(/^\/api\/admin\/verifications\/([^/]+)\/review$/);if(m&&request.method==='POST')return verificationReview(request,env,m[1]);if(u.pathname==='/api/admin/cms/posts'&&(request.method==='GET'||request.method==='POST'))return cmsPosts(request,env);if(u.pathname==='/api/admin/cms/media'&&request.method==='GET')return cmsMediaList(request,env);if(u.pathname==='/api/admin/cms/media'&&request.method==='POST')return cmsMediaUpload(request,env);if(u.pathname==='/api/admin/ai/status'&&request.method==='GET')return aiStatus(request,env);if(u.pathname==='/api/admin/ai/ask'&&request.method==='POST')return aiAsk(request,env);
return handleAdminV1(request,env)}
